<script setup lang="ts">import{onMounted,ref}from'vue';import{request}from'../api/client';interface Message{id:number;sender_name:string;channel_id:string;channel_type:number;content_type:number;payload:unknown;status:string;created_at:string;recalled_at?:string}const items=ref<Message[]>([]),selected=ref<Message|null>(null),reason=ref('');async function load(){items.value=await request<Message[]>('/v1/ops/messages')}async function remove(){if(!selected.value)return;await request(`/v1/ops/messages/${selected.value.id}`,{method:'DELETE',body:JSON.stringify({reason:reason.value})});selected.value=null;await load()}onMounted(load)</script>
<template><div class="page"><div class="heading"><div><h1>消息审计</h1><p>消息元数据、协议类型、发送状态与管理员撤回</p></div><button @click="load">刷新</button></div><div class="table"><table><thead><tr><th>发送者</th><th>频道</th><th>类型</th><th>状态</th><th>时间</th><th></th></tr></thead><tbody><tr v-for="m in items" :key="m.id"><td>{{m.sender_name}}<small>ID {{m.id}}</small></td><td>{{m.channel_id}}<small>{{m.channel_type===1?'私聊':'群聊'}}</small></td><td>{{m.content_type}}</td><td>{{m.recalled_at?'已撤回':m.status}}</td><td>{{new Date(m.created_at).toLocaleString()}}</td><td><button v-if="!m.recalled_at" class="link" @click="selected=m;reason=''">撤回</button></td></tr></tbody></table></div><div v-if="selected" class="backdrop" @click.self="selected=null"><form class="dialog" @submit.prevent="remove"><h2>管理员撤回消息</h2><label>原因<textarea v-model.trim="reason" required minlength="2"></textarea></label><div class="actions"><button type="button" @click="selected=null">取消</button><button class="primary">确认撤回</button></div></form></div></div></template><style scoped>@import '../design/admin-page.css';</style>
